using Contoso.Scoring;

namespace Contoso.Scoring.Tests;

[TestClass]
public sealed class ScoreCalculatorTests
{
    private readonly ScoreCalculator _calculator = new();

    // --- CalculatePercentage ---

    [TestMethod]
    [DataRow(10, 10, 100.0, DisplayName = "Perfect score")]
    [DataRow(0, 10, 0.0, DisplayName = "Zero correct")]
    [DataRow(7, 10, 70.0, DisplayName = "Partial score")]
    [DataRow(1, 3, 33.333333333333336, DisplayName = "Repeating decimal")]
    public void CalculatePercentage_ValidInputs_ReturnsExpected(int correct, int total, double expected)
    {
        var result = _calculator.CalculatePercentage(correct, total);

        Assert.AreEqual(expected, result);
    }

    [TestMethod]
    public void CalculatePercentage_Result_IsInValidRange()
    {
        var result = _calculator.CalculatePercentage(7, 10);

        Assert.IsInRange(result, 0.0, 100.0);
        Assert.IsGreaterThan(0.0, result);   // result > 0
        Assert.IsLessThan(100.0, result);    // result < 100
    }

    [TestMethod]
    public void CalculatePercentage_PerfectScore_IsNotLessThan100()
    {
        var result = _calculator.CalculatePercentage(10, 10);

        Assert.IsInRange(result, 0.0, 100.0);
        Assert.AreEqual(100.0, result);
    }

    [TestMethod]
    public void CalculatePercentage_ZeroTotal_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculatePercentage(0, 0));
    }

    [TestMethod]
    public void CalculatePercentage_NegativeCorrect_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculatePercentage(-1, 10));
    }

    [TestMethod]
    public void CalculatePercentage_CorrectExceedsTotal_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculatePercentage(11, 10));
    }

    // --- GetGrade ---

    [TestMethod]
    [DataRow(100.0, "A", DisplayName = "100 → A")]
    [DataRow(90.0, "A", DisplayName = "90 boundary → A")]
    [DataRow(89.9, "B", DisplayName = "89.9 → B")]
    [DataRow(80.0, "B", DisplayName = "80 boundary → B")]
    [DataRow(79.9, "C", DisplayName = "79.9 → C")]
    [DataRow(70.0, "C", DisplayName = "70 boundary → C")]
    [DataRow(69.9, "D", DisplayName = "69.9 → D")]
    [DataRow(60.0, "D", DisplayName = "60 boundary → D")]
    [DataRow(59.9, "F", DisplayName = "59.9 → F")]
    [DataRow(0.0, "F", DisplayName = "0 → F")]
    public void GetGrade_AtBoundaries_ReturnsCorrectGrade(double percentage, string expected)
    {
        var result = _calculator.GetGrade(percentage);

        Assert.AreEqual(expected, result);
    }

    // --- NormalizeScore ---

    [TestMethod]
    public void NormalizeScore_MidRange_ReturnsExpectedPercentage()
    {
        var result = _calculator.NormalizeScore(50.0, 200.0);

        Assert.AreEqual(25.0, result);
        Assert.IsInRange(result, 0.0, 100.0);
    }

    [TestMethod]
    public void NormalizeScore_ExceedsMax_CapsAt100()
    {
        var result = _calculator.NormalizeScore(250.0, 200.0);

        Assert.AreEqual(100.0, result);
        Assert.IsLessThan(101.0, result); // never above 100
    }

    [TestMethod]
    public void NormalizeScore_ZeroRaw_ReturnsZero()
    {
        var result = _calculator.NormalizeScore(0.0, 100.0);

        Assert.AreEqual(0.0, result);
    }

    [TestMethod]
    public void NormalizeScore_NegativeRaw_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.NormalizeScore(-1.0, 100.0));
    }

    [TestMethod]
    public void NormalizeScore_ZeroMax_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.NormalizeScore(50.0, 0.0));
    }
}

