     [DataRow(60.0, "D", DisplayName = "60 boundary → D")]
     [DataRow(59.9, "F", DisplayName = "59.9 → F")]
     [DataRow(0.0, "F", DisplayName = "0 → F")]
     public void GetGrade_AtBoundaries_ReturnsCorrectGrade(double percentage, string expected)
     {
         var result = _calculator.GetGrade(percentage);

         Assert.AreEqual(expected, result);
     }

     // --- NormalizeScore ---

     [TestMethod]
     public void NormalizeScore_MidRange_ReturnsExpectedPercentage()
     {
         var result = _calculator.NormalizeScore(50.0, 200.0);

         Assert.AreEqual(25.0, result);
         Assert.IsInRange(0.0, 100.0, result);
     }

     [TestMethod]
     public void NormalizeScore_ExceedsMax_CapsAt100()
     {
         var result = _calculator.NormalizeScore(250.0, 200.0);

         Assert.AreEqual(100.0, result);
         Assert.IsLessThanOrEqualTo(100.0, result);
     }

     [TestMethod]
     public void NormalizeScore_AtMax_Returns100()
     {
         var result = _calculator.NormalizeScore(200.0, 200.0);

         Assert.AreEqual(100.0, result);
     }

     [TestMethod]
     public void NormalizeScore_ZeroRaw_ReturnsZero()
     {
         var result = _calculator.NormalizeScore(0.0, 100.0);

         Assert.AreEqual(0.0, result);
         Assert.IsLessThanOrEqualTo(0.0, result);
     }

     [TestMethod]
     public void NormalizeScore_NegativeRaw_Throws()
     {
         Assert.ThrowsExactly<ArgumentOutOfRangeException>(
             () => _calculator.NormalizeScore(-1.0, 100.0));
     }

     [TestMethod]
     public void NormalizeScore_ZeroMax_Throws()
     {
         Assert.ThrowsExactly<ArgumentOutOfRangeException>(
             () => _calculator.NormalizeScore(50.0, 0.0));
     }
